@Override    public void postProcessMergedBeanDefinition(RootBeanDefinition beanDefinition, Class&lt;?&gt; beanType, String beanName) &#123;        //查找注入注解的元数据        InjectionMetadata metadata = findAutowiringMetadata(beanName, beanType, null);        //放入checkedElements集合中        metadata.checkConfigMembers(beanDefinition);    &#125;private InjectionMetadata findAutowiringMetadata(String beanName, Class&lt;?&gt; clazz, @Nullable PropertyValues pvs) &#123;    // Fall back to class name as cache key, for backwards compatibility with custom callers.    String cacheKey = (StringUtils.hasLength(beanName) ? beanName : clazz.getName());    // Quick check on the concurrent map first, with minimal locking.    //从缓存中获取    InjectionMetadata metadata = this.injectionMetadataCache.get(cacheKey);    //return (metadata == null || metadata.targetClass != clazz);    //若元数据不为空  或者 元数据的目标类和当前的类不一样    if (InjectionMetadata.needsRefresh(metadata, clazz)) &#123;        synchronized (this.injectionMetadataCache) &#123;            metadata = this.injectionMetadataCache.get(cacheKey);            if (InjectionMetadata.needsRefresh(metadata, clazz)) &#123;                if (metadata != null) &#123;                    metadata.clear(pvs);                &#125;                //构建元数据                metadata = buildAutowiringMetadata(clazz);                //放入缓存                this.injectionMetadataCache.put(cacheKey, metadata);            &#125;        &#125;    &#125;    return metadata;&#125;private InjectionMetadata buildAutowiringMetadata(final Class&lt;?&gt; clazz) &#123;    List&lt;InjectionMetadata.InjectedElement&gt; elements = new ArrayList&lt;&gt;();    Class&lt;?&gt; targetClass = clazz;    do &#123;        final List&lt;InjectionMetadata.InjectedElement&gt; currElements = new ArrayList&lt;&gt;();        //处理字段上的注解         ReflectionUtils.doWithLocalFields(targetClass, field -&gt; &#123;            //循环三个(可能两个)注解类型，并返回属性            AnnotationAttributes ann = findAutowiredAnnotat