private LifecycleMetadata buildLifecycleMetadata(final Class&lt;?&gt; clazz) &#123;    List&lt;LifecycleElement&gt; initMethods = new ArrayList&lt;&gt;();    List&lt;LifecycleElement&gt; destroyMethods = new ArrayList&lt;&gt;();    Class&lt;?&gt; targetClass = clazz;    do &#123;        final List&lt;LifecycleElement&gt; currInitMethods = new ArrayList&lt;&gt;();        final List&lt;LifecycleElement&gt; currDestroyMethods = new ArrayList&lt;&gt;();        ReflectionUtils.doWithLocalMethods(targetClass, method -&gt; &#123;            if (this.initAnnotationType != null &amp;&amp; method.isAnnotationPresent(this.initAnnotationType)) &#123;                LifecycleElement element = new LifecycleElement(method);                currInitMethods.add(element);                if (logger.isTraceEnabled()) &#123;                    logger.trace(&quot;Found init method on class [&quot; + clazz.getName() + &quot;]: &quot; + method);                &#125;            &#125;            if (this.destroyAnnotationType != null &amp;&amp; method.isAnnotationPresent(this.destroyAnnotationType)) &#123;                currDestroyMethods.add(new LifecycleElement(method));                if (logger.isTraceEnabled()) &#123;                    logger.trace(&quot;Found destroy method on class [&quot; + clazz.getName() + &quot;]: &quot; + method);                &#125;            &#125;        &#125;);        initMethods.addAll(0, currInitMethods);        destroyMethods.addAll(currDestroyMethods);        targetClass = targetClass.getSuperclass();    &#125;        while (targetClass != null &amp;&amp; targetClass != Object.class);    return new LifecycleMetadata(clazz, initMethods, destroyMethods);&#125;



